      "אַלְמָנָה נִזּוֹנֶת מִנִּכְסֵי יְתוֹמִים, מַעֲשֵׂה יָדֶיהָ שֶׁלָּהֶן, וְאֵין חַיָּבִין בִּקְבוּרָתָהּ. יוֹרְשֶׁיהָ, יוֹרְשֵׁי כְתֻבָּתָהּ, חַיָּבִין בִּקְבוּרָתָהּ:",
      "אַלְמָנָה, בֵּין מִן הָאֵרוּסִין בֵּין מִן הַנִּשּׂוּאִין, מוֹכֶרֶת שֶׁלֹּא בְּבֵית דִּין. רַבִּי שִׁמְעוֹן אוֹמֵר, מִן הַנִּשּׂוּאִין, מוֹכֶרֶת שֶׁלֹּא בְּבֵית דִּין. מִן הָאֵרוּסִין, לֹא תִמְכֹּר אֶלָּא בְּבֵית דִּין, מִפְּנֵי שֶׁאֵין לָהּ מְזוֹנוֹת, וְכָל שֶׁאֵין לָהּ מְזוֹנוֹת, לֹא תִמְכֹּר אֶלָּא בְּבֵית דִּין:",
      "מָכְרָה כְתֻבָּתָהּ אוֹ מִקְצָתָהּ, מִשְׁכְּנָה כְתֻבָּתָהּ אוֹ מִקְצָתָהּ, נָתְנָה כְתֻבָּתָהּ לְאַחֵר אוֹ מִקְצָתָהּ, לֹא תִמְכֹּר אֶת הַשְּׁאָר אֶלָּא בְּבֵית דִּין. וַחֲכָמִים אוֹמְרִים, מוֹכֶרֶת הִיא אֲפִלּוּ אַרְבָּעָה וַחֲמִשָּׁה פְעָמִים, וּמוֹכֶרֶת לִמְזוֹנוֹת שֶׁלֹּא בְּבֵית דִּין, וְכוֹתֶבֶת, לִמְזוֹנוֹת מָכָרְתִּי. וּגְרוּשָׁה לֹא תִמְכֹּר אֶלָּא בְּבֵית דִּין:",
      "אַלְמָנָה שֶׁהָיְתָה כְתֻבָּתָהּ מָאתַיִם וּמָכְרָה שָׁוֶה מָנֶה בְמָאתַיִם אוֹ שָׁוֶה מָאתַיִם בְּמָנֶה, נִתְקַבְּלָה כְתֻבָּתָהּ. הָיְתָה כְתֻבָּתָהּ מָנֶה וּמָכְרָה שָׁוֶה מָנֶה וְדִינָר בְּמָנֶה, מִכְרָהּ בָּטֵל. אֲפִלּוּ הִיא אוֹמֶרֶת אַחֲזִיר אֶת הַדִּינָר לַיּוֹרְשִׁין, מִכְרָהּ בָּטֵל. רַבָּן שִׁמְעוֹן בֶּן גַּמְלִיאֵל אוֹמֵר, לְעוֹלָם מִכְרָהּ קַיָּם עַד שֶׁתְּהֵא שָׁם כְּדֵי שֶׁתְּשַׁיֵּר בְּשָׂדֶה בַּת תִּשְׁעָה קַבִּים, וּבְגִנָּה בַּת חֲצִי קַב, וּכְדִבְרֵי רַבִּי עֲקִיבָא בֵּית רֹבַע. הָיְתָה כְתֻבָּתָהּ אַרְבַּע מֵאוֹת זוּז, וּמָכְרָה לָזֶה בְמָנֶה וְלָזֶה בְמָנֶה וְלָאַחֲרוֹן יָפֶה מָנֶה וְדִינָר בְּמָנֶה, שֶׁל אַחֲרוֹן בָּטֵל וְשֶׁל כֻּלָּן מִכְרָן קַיָּם:",
      "שׁוּם הַדַּיָּנִין שֶׁפִּחֲתוּ שְׁתוּת אוֹ הוֹסִיפוּ שְׁתוּת, מִכְרָן בָּטֵל. רַבָּן שִׁמְעוֹן בֶּן גַּמְלִיאֵל אוֹמֵר, מִכְרָן קַיָּם. אִם כֵּן מַה כֹּחַ בֵּית דִּין יָפֶה. אֲבָל אִם עָשׂוּ אִגֶּרֶת בִּקֹּרֶת, אֲפִלּוּ מָכְרוּ שָׁוֶה מָנֶה בְּמָאתַיִם, אוֹ שָׁוֶה מָאתַיִם בְּמָנֶה, מִכְרָן קַיָּם:",
      "הַמְמָאֶנֶת, הַשְּׁנִיָּה, וְהָאַיְלוֹנִית, אֵין לָהֶם כְּתֻבָּה וְלֹא פֵרוֹת, וְלֹא מְזוֹנוֹת, וְלֹא בְלָאוֹת. וְאִם מִתְּחִלָּה נְשָׂאָהּ לְשֵׁם אַיְלוֹנִית, יֶשׁ לָהּ כְּתֻבָּה. אַלְמָנָה לְכֹהֵן גָּדוֹל, גְּרוּשָׁה וַחֲלוּצָה לְכֹהֵן הֶדְיוֹט, מַמְזֶרֶת וּנְתִינָה לְיִשְׂרָאֵל, בַּת יִשְׂרָאֵל לְנָתִין וּלְמַמְזֵר, יֶשׁ לָהֶן כְּתֻבָּה:"
